sp_widget.client_script:
api.controller=function($location) {
    var c = this;

    c.toggleView = function(row) {
        row.expanded = !row.expanded;
    };

    c.goToFeedback = function(row) {
        $location.path('/student_feedback').search('ticket', row.sysId);
    };
}

sp_widget.css:
.cfa-hero{
  background:linear-gradient(135deg,#0d9488,#0f766e);
  color:#fff;border-radius:14px;padding:26px;margin-bottom:20px;
}
.cfa-hero h3{font-size:20px;margin-bottom:5px}
.cfa-hero p{font-size:13.5px;opacity:.92}

.cfa-kpi-grid{
  display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));
  gap:14px;margin-bottom:20px;
}
.cfa-kpi{
  background:#fff;border:1px solid #e2e8f0;border-radius:14px;
  padding:17px;display:flex;align-items:center;gap:12px;
}
.cfa-kpi-ic{font-size:24px}
.cfa-kpi-num{font-size:24px;font-weight:800;line-height:1}
.cfa-kpi-lbl{font-size:11.5px;color:#64748b;margin-top:3px}

.cfa-card{background:#fff;border:1px solid #e2e8f0;border-radius:14px;padding:20px}
.cfa-card h4{font-size:15px;margin-bottom:14px}
.cfa-tbl{width:100%;border-collapse:collapse;font-size:13px}
.cfa-tbl th{
  text-align:left;padding:9px 11px;background:#f8fafc;color:#64748b;
  font-size:11px;text-transform:uppercase;border-bottom:1.5px solid #e2e8f0;
}
.cfa-tbl td{padding:10px 11px;border-bottom:1px solid #e2e8f0;vertical-align:top}
.cfa-muted{color:#64748b;font-size:11px}
.cfa-empty{text-align:center;padding:30px;color:#64748b;font-size:13px}

.cfa-badge{padding:3px 9px;border-radius:20px;font-size:11px;font-weight:700}
.cfa-b-critical{background:#ede9fe;color:#7c3aed}
.cfa-b-high{background:#fee2e2;color:#dc2626}
.cfa-b-medium{background:#fef3c7;color:#d97706}
.cfa-b-low{background:#dcfce7;color:#16a34a}
.cfa-s-active{background:#dbeafe;color:#2563eb}
.cfa-s-monitoring{background:#fef3c7;color:#d97706}
.cfa-s-resolved{background:#dcfce7;color:#16a34a}
.cfa-s-closed{background:#e2e8f0;color:#475569}

.cfa-actions{display:flex;gap:6px}
.cfa-btn-sm{
  padding:5px 11px;font-size:11.5px;border-radius:7px;border:1px solid #e2e8f0;
  background:#fff;cursor:pointer;font-weight:700;
}
.cfa-btn-sm:hover{background:#f1f5f9}
.cfa-btn-fb{color:#0d9488;border-color:#ccfbf1}
.cfa-detail-row td{background:#f8fafc}
.cfa-detail-box{padding:12px 14px;font-size:12.5px;color:#334155;line-height:1.7}

sp_widget.script:
(function() {

    var user = gs.getUser();
    data.userName = user.getDisplayName();

    // Priority choice value → CSS class (matches real choice values: 1=Critical, 2=High, 3=Medium, 4=Low)
    var priorityClassMap = {'1':'critical', '2':'high', '3':'medium', '4':'low'};

    var fc = new GlideRecord('x_snc_campus_foo_1_food_complaint');
    fc.addQuery('student.user', gs.getUserID());
    fc.orderByDesc('opened_at');
    fc.query();

    data.requests = [];
    var total = 0, active = 0, resolved = 0, feedbackEligible = 0;

    while (fc.next()) {
        total++;

        var state = fc.state.toString();
        if (state == 'resolved') {
            resolved++;
        } else {
            active++;
        }

        var isFbEligible = (fc.feedback_eligible == true);
        if (isFbEligible) {
            feedbackEligible++;
        }

        data.requests.push({
            sysId: fc.getUniqueValue(),
            number: fc.number.toString(),
            useCase: fc.use_case.getDisplayValue(),
            messHall: fc.mess_hall.getDisplayValue(),
            mealType: fc.meal_type.getDisplayValue(),
            priority: fc.priority.getDisplayValue() || 'Not set',
            priorityClass: priorityClassMap[fc.priority.toString()] || 'medium',
            state: fc.state.getDisplayValue(),
            stateClass: state,
            openedAt: fc.opened_at.getDisplayValue(),
            description: fc.description.toString(),
            resolutionNotes: fc.resolution_notes ? fc.resolution_notes.toString() : '',
            feedbackEligible: isFbEligible,
            expanded: false
        });
    }

    data.kpi = {
        total: total,
        active: active,
        resolved: resolved,
        feedbackEligible: feedbackEligible
    };

})();
